                "• 信息收集范围调整：明确实际收集的信息类型，包括账号信息、设备与网络信息、使用行为信息、反馈信息、用户设置信息、PIN码验证信息",
                "• 删除不适用条款：移除了敏感个人信息（身份证号、银行卡）、未成年人专项规则、第三方合作共享、境外信息转移等当前版本不涉及的内容",
                "• 新增数据加密说明：明确密码、PIN码等敏感信息将进行加密存储",
                "• 明确存储地点：用户个人信息存储在中华人民共和国境内，不转移至境外",
                "• 精简章节结构：从原有的五大章节精简为四大章节",
                "",
                "[color:#ffd93d]【温馨提示】[/color]",
