                "• 经验加成卡：使用后30分钟内经验获取提升10%/25%/50%，生效于每日签到与活动签到经验结算，可重复使用覆盖已有加成",
                "• 幸运币：使用后激活幸运状态，下一次提取时稀有项概率翻倍，抽卡时自动消耗1枚",
