                "• 类型Tag位置调整：道具类型Tag（消耗品/材料/徽章）移至卡片右上角，采用边框风格与稀有度配色",
                "• 一行6列网格布局：桌面端一行显示6个道具卡片，窄屏自动降级为4/3/2列",
                "• 邮件系统对接仓库：邮件附件新增warehouse类型，领取时自动调用warehouseAddItem发放到仓库；邮件详情中仓库道具图标、名称、数量从WAREHOUSE_ITEMS动态读取，新增道具无需修改邮件系统",
