                "• 邮件内图片查看器功能栏隐藏：在邮件内使用图片查看器查看背景时隐藏右侧功能栏，不影响版本更新记录中查看更新图片的功能栏",
                "• 兑换历史记录排版优化：兑换时间放到和兑换账户一行显示，优化布局结构",
