                "• 修复图片查看器动态背景元素残留：查看动态背景后再查看静态背景时，右上角\"动态背景\"标签和右下角日期数字不再错误显示",
                "• 修复版本更新记录图片背景残留：在邮件中查看背景后，版本更新记录图片不再显示之前的背景",
