                "今天我们发布了 RC 2.6.4.8 版本更新，本次更新为页面时钟组件带来了多项个性化定制功能，以及追加了天气组件详情弹窗功能和多项视觉优化，让天气信息展示更加丰富美观！",
                "[color:#d45d79]【新增功能】[/color]",
                "- 天气组件折线图切换：天气组件中新增折线图展示未来7天内的天气变化趋势，更直观地了解天气变化",
                "• 天气详情弹窗：天气组件中的8个信息卡片（体感温度、湿度、风向风力、气压、能见度、紫外线、降水概率、空气质量）现在都可以点击查看详情，每个详情页都包含主数值展示、等级参考、知识科普和温馨提示等丰富内容",
                "• 名言打字机效果开关：组件调整弹窗中新增\"名言打字机效果\"开关，关闭后名言区域文本直接显示，开启后保留打字机动画效果",
                "• 显示秒数：时钟调整弹窗中新增\"显示秒数\"开关，开启后时间显示包含秒数，精确到秒",
                "• 分别调整字体大小：时钟调整弹窗中新增4个独立滑块，可分别调整时钟数字、日期、天气、名言的字体大小，时钟数字默认比其他组件更大更醒目",
                "• 新增字体样式：新增粗体、手写体、细体3种字体样式，加上原有3种共6种字体，提供更多个性化选择",
                "• 组件初始化功能：组件设置弹窗中新增\"初始化\"大类和\"组件初始化\"淡红色按钮，点击后弹出确认弹窗，确认后一键重置组件所有设置到默认状态（默认仅开启显示日期）",
                "[color:#4ecdc4]【优化改进】[/color]",
                "• 跳转目标按钮布局：跳转目标按钮改为一行两个排版，按钮之间有间距，视觉上更清晰独立",
                "• 时钟调整弹窗滚动：时钟调整弹窗内容区域改为可滚动浏览，滚动条使用自定义半透明样式，内容过多时不会溢出弹窗",
                "• 组件初始化按钮间距：调整组件初始化按钮与弹窗底部边框的距离，避免紧贴边框，视觉更舒适",
                "• 详情弹窗布局：采用左右两栏设计，左侧为大卡片展示主数值（粘性定位，滚动时始终可见），右侧为详细信息列表，弹窗宽度从560px扩大到860px，视觉效果更大气",
                "• 字体颜色优化：详情弹窗所有文字统一为白色/亮色，配合渐变背景，大幅提升可读性",
                "• 标题栏简化：移除详情弹窗左上角返回按钮，仅保留右上角关闭按钮，界面更简洁统一",
                "• 透明主题适配：选择城市弹窗完整适配透明主题，采用半透明白色背景+毛玻璃效果+白色文字，与整体透明风格完美统一",
