                "• 侧边栏模式背景优化：启用侧边栏模式后背景为正常透明效果，而非模糊效果，视觉更清晰",
                "• 侧边栏模式天气排版：天气设置面板中天气预览和刷新按钮移至温度单位条目下方，布局更合理（仅侧边栏模式生效）",
