                "[color:#ff6b6b]【修复问题】[/color]",
                "• 组件信息弹窗层级：修复弹窗显示在便签窗口下方的问题，现在弹窗会正确显示在最上层",
                "• 排序功能：修复按创建时间/修改时间排序不生效的问题，现已正常工作",
                "• 置顶功能：修复置顶后便签未正确标记和排序的问题，现使用isPinned属性标记置顶状态",
