        monthHeader.appendChild(monthLine);
        monthHeader.appendChild(monthTitle);
        monthHeader.appendChild(monthLine.cloneNode(true));
        contentArea.appendChild(monthHeader);
        
        var buttonsContainer = document.createElement('div');
